// 24h ago). status filter: ” (all visible), UPCOMING, ACTIVE or ENDED.
// Ordering: active (ending soonest first), then upcoming, then ended.
func (q *Queries) SearchAuctions(ctx context.Context, arg SearchAuctionsParams) ([]SearchAuctionsRow, error) {
	rows, err := q.db.Query(ctx, searchAuctions,
		arg.Now,
		arg.Pattern,
		arg.Status,
		arg.Off,
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SearchAuctionsRow{}
	for rows.Next() {
		var i SearchAuctionsRow
		if err := rows.Scan(
			&i.Auction.ID,
			&i.Auction.SellerID,
			&i.Auction.Title,
			&i.Auction.Description,
			&i.Auction.StartPrice,
			&i.Auction.MinIncrement,
			&i.Auction.MaxIncrement,
			&i.Auction.CurrentPrice,
			&i.Auction.HighestBidderID,
			&i.Auction.BidCount,
			&i.Auction.StartTime,
			&i.Auction.EndTime,
			&i.Auction.OriginalEndTime,
			&i.Auction.ContactInfo,
			&i.Auction.ShippingMethod,
			&i.Auction.ShippingFee,
			&i.Auction.CreatedAt,
			&i.Auction.UpdatedAt,
			&i.Auction.SettledAt,
			&i.Auction.EndingSoonNotifiedAt,
			&i.SellerName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const updateAuctionContent = `-- name: UpdateAuctionContent :one
UPDATE auctions
SET title = $2, description = $3, start_price = $4, current_price = $4,
    min_increment = $5, max_increment = $6, start_time = $7, end_time = $8,
    original_end_time = $8, contact_info = $9, shipping_method = $10,
    shipping_fee = $11, updated_at = $12
WHERE id = $1
RETURNING id, seller_id, title, description, start_price, min_increment, max_increment, current_price, highest_bidder_id, bid_count, start_time, end_time, original_end_time, contact_info, shipping_method, shipping_fee, created_at, updated_at, settled_at, ending_soon_notified_at
`

type UpdateAuctionContentParams struct {
	ID             uuid.UUID `json:"id"`
	Title          string    `json:"title"`
	Description    string    `json:"description"`
	StartPrice     int64     `json:"start_price"`
	MinIncrement   int64     `json:"min_increment"`
	MaxIncrement   int64     `json:"max_increment"`
	StartTime      time.Time `json:"start_time"`
	EndTime        time.Time `json:"end_time"`
	ContactInfo    string    `json:"contact_info"`
	ShippingMethod string    `json:"shipping_method"`
	ShippingFee    int64     `json:"shipping_fee"`
	UpdatedAt      time.Time `json:"updated_at"`
}

// Only valid while the auction has not started; the caller checks status
// under the row lock obtained by GetAuctionForUpdate.
func (q *Queries) UpdateAuctionContent(ctx context.Context, arg UpdateAuctionContentParams) (Auction, error) {
	row := q.db.QueryRow(ctx, updateAuctionContent,
		arg.ID,
		arg.Title,
		arg.Description,
		arg.StartPrice,
		arg.MinIncrement,
		arg.MaxIncrement,
		arg.StartTime,
		arg.EndTime,
		arg.ContactInfo,
		arg.ShippingMethod,
		arg.ShippingFee,
		arg.UpdatedAt,
	)
	var i Auction
	err := row.Scan(
		&i.ID,
		&i.SellerID,
		&i.Title,
		&i.Description,
		&i.StartPrice,
		&i.MinIncrement,
		&i.MaxIncrement,
		&i.CurrentPrice,
		&i.HighestBidderID,
		&i.BidCount,
		&i.StartTime,
		&i.EndTime,
		&i.OriginalEndTime,
		&i.ContactInfo,
		&i.ShippingMethod,
		&i.ShippingFee,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.SettledAt,
		&i.EndingSoonNotifiedAt,
	)
	return i, err
}
